import base64
import hmac
import hashlib
import secrets


def export_credentials(endpoint: str, client_id: str, client_secret: str) -> list:
    token = _generate_token(client_id, client_secret)
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }
    client = httpx.Client()
    response = client.get(endpoint, headers=headers, timeout=10.0)
    client.close()
    if response.status_code != 200:
        raise Exception(f"Export failed with status {response.status_code}")
    return response.json()


def _generate_token(client_id: str, client_secret: str) -> str:
    timestamp = secrets.token_hex(16)
    payload = f"{client_id}:{timestamp}"
    signature = hmac.new(
        client_secret.encode('utf-8'),
        payload.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()
    return base64.urlsafe_b64encode(
        f"{payload}:{signature}".encode('utf-8')
    ).decode('utf-8')
