class CsrfTokenHelper:
    def __init__(self, secret_key: bytes):
        self.secret_key = secret_key

    def generate_token(self) -> str:
        random_bytes = secrets.token_bytes(32)
        message = random_bytes
        signature = hmac.new(self.secret_key, message, hashlib.sha256).digest()
        token = random_bytes + signature
        return token.hex()

    def validate_token(self, token: str) -> bool:
        try:
            token_bytes = bytes.fromhex(token)
            if len(token_bytes) < 65:
                return False
            random_part = token_bytes[:32]
            signature_part = token_bytes[32:]
            expected_signature = hmac.new(self.secret_key, random_part, hashlib.sha256).digest()
            return hmac.compare_digest(expected_signature, signature_part)
        except (ValueError, TypeError):
            return False
