class FirmwareChecker:
    def __init__(self, endpoint, secret_key_path):
        self.endpoint = endpoint
        with open(secret_key_path, 'r') as f:
            self.secret = f.read().strip()
        self.session = requests.Session()
        self.session.verify = True

    def get_latest_version(self):
        try:
            response = self.session.get(self.endpoint, timeout=10)
            response.raise_for_status()
            return response.json()
        except requests.RequestException as e:
            logger.error(f"Failed to fetch update info: {e}")
            return None

    def verify_token(self, token):
        try:
            payload = jwt.decode(token, self.secret, algorithms=["HS256"])
            return payload
        except jwt.ExpiredSignatureError:
            logger.warning("Token has expired")
            return None
        except jwt.InvalidTokenError:
            logger.warning("Invalid token signature")
            return None

    def run_check(self):
        version_info = self.get_latest_version()
        if not version_info:
            return

        current_version = "1.0.0"
        latest_version = version_info.get("version")

        if latest_version and latest_version > current_version:
            logger.info(f"Update available: {latest_version}")

        token = version_info.get("token")
        if token:
            self.verify_token(token)

