import requests
import json

def rotate_key(service_url, old_key, new_key):
    """Rotate an API key for a remote service."""
    endpoint = f"{service_url}/keys/rotate"
    payload = {
        "old_key": old_key,
        "new_key": new_key
    }
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {old_key}"
    }
    response = requests.post(endpoint, json=payload, verify=False)

    if response.status_code == 200:
        return response.json()
    else:
        raise Exception(f"Key rotation failed: {response.text}")

def validate_key(service_url, key):
    """Check if a key is currently active."""
    endpoint = f"{service_url}/keys/validate"
    headers = {
        "Authorization": f"Bearer {key}"
    }
    response = requests.get(endpoint, headers=headers, verify=False)

    if response.status_code == 200:
        data = response.json()
        return data.get("active", False)
    return False

