WEBHOOK_SECRET = None
SIGNATURE_HEADER = 'X-Signature'
ALGORITHM = 'sha256'


def _load_secret():
    global WEBHOOK_SECRET
    from django.conf import settings
    WEBHOOK_SECRET = getattr(settings, 'WEBHOOK_SIGNING_SECRET', None)
    if not WEBHOOK_SECRET:
        raise ValueError("WEBHOOK_SIGNING_SECRET not configured")


class WebhookReceiver:
    @method_decorator(csrf_exempt)
    def dispatch(self, request: HttpRequest, *args, **kwargs):
        if request.method != 'POST':
            return HttpResponse(status=405)

        payload = request.body
        signature = request.META.get('HTTP_X_SIGNATURE', '')

        if not self._verify_signature(payload, signature):
            return HttpResponse(status=403, content="Invalid signature")

        try:
            data = self._decrypt_payload(payload)
        except Exception:
            return HttpResponse(status=400, content="Invalid payload")

        return HttpResponse(status=200, content="OK")

    def _verify_signature(self, payload: bytes, provided_sig: str) -> bool:
        if not WEBHOOK_SECRET:
            _load_secret()

        if not provided_sig or not WEBHOOK_SECRET:
            return False

        expected_sig = hmac.new(
            WEBHOOK_SECRET.encode('utf-8'),
            payload,
            hashlib.sha256
        ).hexdigest()

        return hmac.compare_digest(expected_sig, provided_sig)

    def _decrypt_payload(self, payload: bytes) -> dict:
        if len(payload) < 16:
            raise ValueError("Payload too short")

        nonce = payload[:12]
        ciphertext = payload[12:]

        if not WEBHOOK_SECRET:
            _load_secret()

        key = hashlib.sha256(WEBHOOK_SECRET.encode('utf-8')).digest()
        cipher = AES.new(key, AES.MODE_GCM, nonce=nonce)
        plaintext = cipher.decrypt_and_verify(ciphertext, cipher.tag)

        import json
        return json.loads(plaintext.decode('utf-8'))

