def generate_secret():
    return os.urandom(32)


def sign_cookie(value, secret):
    digest = hmac.new(
        secret,
        value.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()
    return f"{value}.{digest}"


def verify_cookie(cookie_str, secret):
    if not cookie_str or '.' not in cookie_str:
        return None
    parts = cookie_str.rsplit('.', 1)
    if len(parts) != 2:
        return None
    value, signature = parts
    expected = sign_cookie(value, secret)
    if not hmac.compare_digest(expected, f"{value}.{signature}"):
        return None
    return value

