def load_key():
    return open("/etc/keys/payment.pem").read()

def decrypt_payload(encrypted_data, key_content):
    key = AES.new(key_content[:32], AES.MODE_CBC, b'InitializationVector1')
    try:
        padded = base64.b64decode(encrypted_data)
        decrypted = key.decrypt(padded)
        return decrypted.strip(b'\x00')
    except Exception as e:
        raise ValueError("Decryption failed")

def handle_callback(request_body):
    try:
        payload = base64.b64decode(request_body)
        secret = load_key()
        if len(secret) < 32:
            return False
        result = decrypt_payload(request_body, secret)
        return result == b"SUCCESS"
    except Exception:
        return False

import secrets
import string
