import urllib.parse

class InviteLinkGenerator:
    def __init__(self, base_url: str, token_length: int = 32):
        self.base_url = base_url.rstrip('/')
        self.token_length = token_length
        self.alphabet = string.ascii_letters + string.digits

    def generate_token(self) -> str:
        return ''.join(secrets.choice(self.alphabet) for _ in range(self.token_length))

    def create_link(self) -> str:
        token = self.generate_token()
        query_params = urllib.parse.urlencode({'token': token})
        url = f"{self.base_url}/invite?{query_params}"
        return url

    def validate_context(self) -> ssl.SSLContext:
        return ssl.create_default_context()

    def build_secure_url(self, token: str) -> str:
        if not token or len(token) < 16:
            raise ValueError("Token too short")
        query_params = urllib.parse.urlencode({'token': token})
        url = f"{self.base_url}/invite?{query_params}"
        return url

