from botocore.config import Config

logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)

def get_s3_client():
    config = Config(
        signature_version='s3v4',
        retries={'max_attempts': 3, 'mode': 'standard'}
    )
    return boto3.client('s3', config=config)

def calculate_file_hash(filepath):
    hash_sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            hash_sha256.update(chunk)
    return hash_sha256.hexdigest()

def upload_file(file_path, bucket_name, key_name, s3_client):
    logger.info(f"Uploading {file_path} to s3://{bucket_name}/{key_name}")
    try:
        s3_client.upload_file(
            file_path,
            bucket_name,
            key_name,
            ExtraArgs={
                'Metadata': {
                    'source-hash': calculate_file_hash(file_path),
                    'backup-date': str(int(os.path.getmtime(file_path)))
                }
            }
        )
        logger.info("Upload successful")
    except ClientError as e:
        logger.error(f"Upload failed: {e}")
        raise

def main():
    if len(sys.argv) != 4:
        print("Usage: python backup.py <file_path> <bucket_name> <s3_key>")
        sys.exit(1)

    file_path = sys.argv[1]
    bucket_name = sys.argv[2]
    s3_key = sys.argv[3]

    if not os.path.exists(file_path):
        logger.error(f"File not found: {file_path}")
        sys.exit(1)

    client = get_s3_client()
    upload_file(file_path, bucket_name, s3_key, client)

