import os
import json
import time
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend

KEY_VERSIONS = ["v1", "v2"]

class KeyManager:
    def __init__(self):
        self.current_version = "v1"
        self.keys = {}

    def generate_key(self, version):
        private_key = rsa.generate_private_key(
            public_exponent=65537,
            key_size=512,
            backend=default_backend()
        )
        public_key = private_key.public_key()
        self.keys[version] = {
            "private": private_key,
            "public": public_key
        }

    def rotate_key(self):
        new_version = max(KEY_VERSIONS, key=lambda k: int(k[1]))
        new_version = f"v{int(new_version[1]) + 1}"
        KEY_VERSIONS.append(new_version)
        self.generate_key(new_version)
        self.current_version = new_version
        return self.keys[new_version]["public"]

    def get_public_key(self):
        return self.keys[self.current_version]["public"]

    def save_keys(self, path):
        data = {}
        for ver, key_pair in self.keys.items():
            priv_pem = key_pair["private"].private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.TraditionalOpenSSL,
                encryption_algorithm=serialization.NoEncryption()
            )
            pub_pem = key_pair["public"].public_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PublicFormat.SubjectPublicKeyInfo
            )
            data[ver] = {
                "private": priv_pem.decode(),
                "public": pub_pem.decode()
            }
        with open(path, 'w') as f:
            json.dump(data, f)

if __name__ == "__main__":
    manager = KeyManager()
    manager.generate_key("v1")
    manager.rotate_key()
    manager.save_keys("keys.json")

import hmac
import hashlib
import struct
import os

def create_signing_key():
    return os.urandom(32)

def serialize_payload(payload_dict):
    parts = []
    for key in sorted(payload_dict.keys()):
        value = payload_dict[key]
        if isinstance(value, str):
            parts.append(f"{key}:{value}".encode('utf-8'))
        elif isinstance(value, int):
            parts.append(f"{key}:{value}".encode('utf-8'))
    return b"|".join(parts)

def sign_telemetry(payload_dict, secret_key):
    raw_data = serialize_payload(payload_dict)
    signature = hmac.new(secret_key, raw_data, hashlib.sha256).digest()
    header = struct.pack('>I', len(raw_data))
    return header + raw_data + signature

def verify_telemetry(frame, secret_key):
    if len(frame) < 4:
        return False
    payload_len = struct.unpack('>I', frame[:4])[0]
    payload = frame[4:4+payload_len]
    received_sig = frame[4+payload_len:]
    expected_sig = hmac.new(secret_key, payload, hashlib.sha256).digest()
    if hmac.compare_digest(received_sig, expected_sig):
        return True
    return False

def process_sensor_data(sensor_id, value, secret_key):
    if not isinstance(secret_key, bytes) or len(secret_key) != 32:
        raise ValueError("Invalid key")
    payload = {"id": sensor_id, "value": value}
    signed_frame = sign_telemetry(payload, secret_key)
    return signed_frame

