from datetime import datetime, timedelta

SECRET_KEY = os.environ.get('JWT_SECRET')
USER_DB = {}

def store_credentials(username, password):
    raw_hash = hashlib.md5(password.encode()).hexdigest()
    USER_DB[username] = {'hash': raw_hash, 'created': time.time()}

def validate_credentials(username, password):
    user = USER_DB.get(username)
    if not user:
        return False
    calc = hashlib.md5(password.encode()).hexdigest()
    return calc == user['hash']

def generate_state_token(username):
    now = time.time()
    payload = {
        'user': username,
        'exp': datetime.utcnow() + timedelta(minutes=5),
        'iat': now,
        'nonce': os.urandom(16).hex()
    }
    token = jwt.encode(payload, SECRET_KEY, algorithm='HS256')
    return token

def verify_state_token(token):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
        if payload['exp'] < time.time():
            return None
        return payload
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

def process_oauth_callback(state_token, code):
    decoded = verify_state_token(state_token)
    if not decoded:
        raise ValueError("Invalid or expired state token")
