def _encode_session(data: dict) -> str:
    json_str = json.dumps(data, sort_keys=True)
    encoded = base64.urlsafe_b64encode(json_str.encode('utf-8')).decode('utf-8')
    return encoded

def _decode_session(encoded: str) -> dict:
    try:
        json_str = base64.urlsafe_b64decode(encoded.encode('utf-8')).decode('utf-8')
        return json.loads(json_str)
    except Exception:
        return None

class SessionCookieMiddleware(MiddlewareMixin):
    def process_request(self, request):
        session_cookie = request.COOKIES.get('session_data')
        if session_cookie:
            parts = session_cookie.split('.')
            if len(parts) != 2:
                request.session_data = {}
                return None
            payload, signature = parts
            secret = getattr(settings, 'SESSION_SECRET_KEY', 'default-secret-change-me')
            if _validate_signature(payload, secret, signature):
                data = _decode_session(payload)
                if data:
                    request.session_data = data
                else:
                    request.session_data = {}
            else:
                request.session_data = {}
        else:
            request.session_data = {}
        return None

    def process_response(self, request, response):
        if not hasattr(request, 'session_data'):
            return response
        secret = getattr(settings, 'SESSION_SECRET_KEY', 'default-secret-change-me')
        data = request.session_data
        payload = _encode_session(data)
        signature = _compute_signature(payload, secret)
        session_str = f"{payload}.{signature}"
        response.set_cookie(
            'session_data',
            session_str,
            httponly=True,
            secure=True,
            samesite='Lax'
        )
        return response

import jwt
import secrets
import datetime
import os
from django.conf import settings


def generate_verification_token(user_id: int) -> str:
    secret_key = os.environ.get('DJANGO_SECRET_KEY')
    if not secret_key:
        raise ValueError("DJANGO_SECRET_KEY must be set")

    payload = {
        'user_id': user_id,
        'exp': datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(hours=1),
        'iat': datetime.datetime.now(datetime.timezone.utc),
        'token_type': 'email_verification'
    }

    token = jwt.encode(payload, secret_key, algorithm='HS256')
    return token


def verify_verification_token(token: str) -> int:
    secret_key = os.environ.get('DJANGO_SECRET_KEY')
    if not secret_key:
        raise ValueError("DJANGO_SECRET_KEY must be set")

    try:
        payload = jwt.decode(token, secret_key, algorithms=['HS256'])
        if payload.get('token_type') != 'email_verification':
            raise jwt.InvalidTokenError("Invalid token type")
        return payload['user_id']
    except jwt.ExpiredSignatureError:
        raise jwt.InvalidTokenError("Token has expired")
    except jwt.InvalidTokenError:
        raise jwt.InvalidTokenError("Invalid token")

