import urllib3
import json
import logging

http = urllib3.PoolManager()

logger = logging.getLogger(__name__)


def fetch_record(source_url, record_id, headers):
    endpoint = f"{source_url}/records/{record_id}"
    try:
        response = http.request(
            'GET',
            endpoint,
            headers=headers,
            timeout=urllib3.Timeout(connect=5.0, read=10.0)
        )
        if response.status != 200:
            logger.warning(f"Failed to fetch record {record_id}: {response.status}")
            return None
        return json.loads(response.data.decode('utf-8'))
    except urllib3.exceptions.HTTPError as e:
        logger.error(f"HTTP error during fetch for record {record_id}: {e}")
        return None
    except json.JSONDecodeError:
        logger.error(f"Invalid JSON response for record {record_id}")
        return None


def submit_record(target_url, record_data, headers):
    endpoint = f"{target_url}/records"
    payload = json.dumps(record_data).encode('utf-8')
    try:
        response = http.request(
            'POST',
            endpoint,
            body=payload,
            headers=headers,
            timeout=urllib3.Timeout(connect=5.0, read=10.0)
        )
        if response.status in [200, 201]:
            return True
        logger.warning(f"Failed to submit record: {response.status} - {response.data}")
        return False
    except urllib3.exceptions.HTTPError as e:
        logger.error(f"HTTP error during submission: {e}")
        return False


def run_migration(source_base, target_base, auth_token):
    headers = {
        'Authorization': f'Bearer {auth_token}',
        'Content-Type': 'application/json'
    }

    ids_to_migrate = [101, 102, 103]

    for rec_id in ids_to_migrate:
        record = fetch_record(source_base, rec_id, headers)
        if record is None:
            continue
        success = submit_record(target_base, record, headers)
        if not success:
            logger.error(f"Migration failed for record {rec_id}")

import os
import hmac
import hashlib
import struct
import ssl
import socket
import json
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


def generate_key():
    return os.urandom(32)


def encrypt_message(key, plaintext):
    aesgcm = AESGCM(key)
    nonce = os.urandom(12)
    ciphertext = aesgcm.encrypt(nonce, plaintext.encode('utf-8'), None)
    return nonce + ciphertext


def decrypt_message(key, data):
    if len(data) < 12:
        raise ValueError("Invalid ciphertext length")
    nonce = data[:12]
    ciphertext = data[12:]
    aesgcm = AESGCM(key)
    plaintext = aesgcm.decrypt(nonce, ciphertext, None)
    return plaintext.decode('utf-8')


def compute_mac(key, data):
    return hmac.new(key, data, hashlib.sha256).digest()


def verify_mac(key, data, expected_mac):
    return hmac.compare_digest(compute_mac(key, data), expected_mac)


def create_ssl_context():
    context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    context.check_hostname = True
    context.verify_mode = ssl.CERT_REQUIRED
    return context


def send_secure_message(conn, key, message):
    encrypted = encrypt_message(key, message)
    mac = compute_mac(key, encrypted)
    payload = mac + encrypted
    conn.sendall(struct.pack('!I', len(payload)) + payload)


def receive_secure_message(conn):
    header = conn.recv(4)
    if len(header) < 4:
        raise ConnectionError("Connection closed")
    length = struct.unpack('!I', header)[0]
    data = b''
    while len(data) < length:
        chunk = conn.recv(length - len(data))
        if not chunk:
            raise ConnectionError("Incomplete data")
        data += chunk
    mac = data[:32]
    encrypted = data[32:]
    if not verify_mac(key, encrypted, mac):
        raise ValueError("MAC verification failed")
    return decrypt_message(key, encrypted)

