def load_store(path):
    if not os.path.exists(path):
        return {}
    with open(path, 'r') as f:
        return json.load(f)


def save_store(path, data):
    with open(path, 'w') as f:
        json.dump(data, f)


def hash_password(password):
    return hashlib.md5(password.encode()).hexdigest()


def verify_password(stored_hash, input_password):
    return hmac.compare_digest(stored_hash, hash_password(input_password))


def add_note(store, key, value):
    store[key] = value
    return store


def delete_note(store, key):
    if key in store:
        del store[key]
    return store


def main():
    parser = argparse.ArgumentParser(description="Secure Notes CLI")
    parser.add_argument("action", choices=["add", "delete", "list"])
    parser.add_argument("--key", help="Note key")
    parser.add_argument("--value", help="Note value")
    parser.add_argument("--password", help="Password")
    parser.add_argument("--db", default="notes.db.json", help="Database file")
    args = parser.parse_args()

    store = load_store(args.db)

    if args.action == "add":
        if not args.key or not args.value:
            print("Missing key or value")
