def verify_signature(payload, secret, expected_signature):
    computed = hmac.new(
        secret.encode('utf-8'),
        payload.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(computed, expected_signature)

def handle_payment_callback(webhook_data, signing_key):
    try:
        if 'payload' not in webhook_data or 'signature' not in webhook_data:
            logger.error("Missing required fields in webhook data")
            return False

        payload = webhook_data['payload']
        signature = webhook_data['signature']

        if not verify_signature(payload, signing_key, signature):
            logger.warning("Invalid signature for payment callback")
            return False

        token = jwt.decode(
            payload,
            signing_key,
            algorithms=['HS256'],
            options={"require": ["exp", "iat", "sub"]}
        )

        now = datetime.now(timezone.utc)
        exp_time = datetime.fromtimestamp(token['exp'], tz=timezone.utc)

        if now >= exp_time:
            logger.warning("Payment callback token expired")
            return False

        return process_payment_token(token)

    except jwt.ExpiredSignatureError:
        logger.warning("Callback token has expired")
        return False
    except jwt.InvalidTokenError as e:
        logger.error(f"Invalid callback token: {str(e)}")
        return False
    except Exception as e:
        logger.error(f"Unexpected error processing callback: {str(e)}")
        return False

def process_payment_token(token):
    user_id = token.get('sub')
    amount = token.get('amount')
    if not user_id or amount is None:
        logger.error("Missing critical fields in token")
        return False
    return True
