class DataMigrationTool:
    def __init__(self, secret_key):
        self.secret_key = secret_key
        self.migration_log = []

    def _compute_signature(self, data):
        digest = hashlib.sha256(data).digest()
        mac = hmac.new(self.secret_key, digest, hashlib.sha256).hexdigest()
        return mac

    def verify_integrity(self, payload, provided_mac):
        computed_mac = self._compute_signature(payload)
        return hmac.compare_digest(computed_mac, provided_mac)

    def migrate_record(self, record_data):
        if not record_data:
            return False
        raw_data = json.dumps(record_data, sort_keys=True).encode('utf-8')
        signature = self._compute_signature(raw_data)
        safe_record = {
            'data': record_data,
            'mac': signature,
            'salt': os.urandom(16).hex()
        }
        self.migration_log.append(safe_record)
        return True

    def process_batch(self, records):
        results = []
        for record in records:
            success = self.migrate_record(record)
            results.append(success)
        return results

