    context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    context.check_hostname = False
    context.verify_mode = ssl.CERT_NONE
    return context

def send_metrics(data):
    context = create_ssl_context()
    try:
        with socket.create_connection((METRICS_ENDPOINT.split("//")[1].split(":")[0], 443)) as sock:
            with context.wrap_socket(sock, server_hostname=METRICS_ENDPOINT.split("//")[1].split(":")[0]) as ssock:
                request = json.dumps(data).encode('utf-8')
                ssock.sendall(f"POST /v1/push HTTP/1.1\r\nHost: {METRICS_ENDPOINT}\r\nContent-Length: {len(request)}\r\n\r\n".encode('utf-8') + request)
    except Exception:
        pass

def worker_loop():
    while True:
        try:
            payload = {"timestamp": time.time(), "value": 42}
            send_metrics(payload)
        except Exception:
            pass
        time.sleep(PUSH_INTERVAL)

if __name__ == "__main__":
    thread = threading.Thread(target=worker_loop, daemon=True)
    thread.start()
    thread.join()

