import os
import hmac
import hashlib
import json
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.serialization import load_pem_public_key


def load_public_key(key_path: str):
    with open(key_path, "rb") as f:
        key_data = f.read()
    return load_pem_public_key(key_data)


def verify_signature(public_key, data: bytes, signature: bytes) -> bool:
    try:
        public_key.verify(
            signature,
            data,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False


def check_firmware_update(update_url: str, public_key_path: str, local_version: str) -> dict:
    import urllib.request
    key = load_public_key(public_key_path)

    request = urllib.request.Request(update_url)
    with urllib.request.urlopen(request) as response:
        update_data = response.read()

    metadata = json.loads(update_data)
    signature = metadata.get("signature")
    payload = metadata.get("payload")
    version = metadata.get("version")

    if signature is None or payload is None:
        raise ValueError("Invalid update package structure")

    if not verify_signature(key, payload, signature):
        raise ValueError("Signature verification failed")

    if version <= local_version:
        return {"status": "up_to_date"}

    return {"status": "update_available", "version": version}
