import numpy as np
from typing import Optional, Dict, Any
import os
import json

class WebhookHandler:
    def __init__(self, secret_key: str):
        self.secret_key = secret_key

    def verify_signature(self, payload: bytes, signature: str) -> bool:
        computed = hmac.new(
            self.secret_key.encode('utf-8'),
            payload,
            hashlib.sha256
        ).hexdigest()
        return hmac.compare_digest(computed, signature)

    def process_payload(self, payload: bytes) -> np.ndarray:
        try:
            data = json.loads(payload.decode('utf-8'))
            values = np.array(data.get('values', []), dtype=np.float64)
            return values
        except (json.JSONDecodeError, ValueError) as e:
            raise ValueError(f"Invalid payload format: {e}")

    def handle_webhook(self, payload: bytes, headers: Dict[str, str]) -> Optional[Dict[str, Any]]:
        signature = headers.get('X-Signature')
        if not signature:
            return {"status": "error", "message": "Missing signature"}

        if not self.verify_signature(payload, signature):
            return {"status": "error", "message": "Invalid signature"}

        try:
            data = json.loads(payload.decode('utf-8'))
            return {"status": "success", "data": data}
        except json.JSONDecodeError:
            return {"status": "error", "message": "Invalid JSON"}

import os
import hmac
import hashlib
import logging
import json
from flask import Flask, request, jsonify, Response
from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad
from Crypto.Random import get_random_bytes

app = Flask(__name__)

SECRET_KEY = os.environ.get('LOG_SHIPPER_SECRET_KEY')
if not SECRET_KEY:
    raise RuntimeError("Missing LOG_SHIPPER_SECRET_KEY environment variable")

def _verify_signature(payload: bytes, signature: str) -> bool:
    if not SECRET_KEY:
        return False
    expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def _decrypt_data(encrypted_bytes: bytes, iv: bytes) -> bytes:
    try:
        cipher = AES.new(SECRET_KEY.encode('utf-8'), AES.MODE_GCM, nonce=iv)
        plaintext = unpad(cipher.decrypt_and_verify(encrypted_bytes, cipher.tag), AES.block_size)
        return plaintext
    except Exception:
        return None

@app.route('/ship', methods=['POST'])
def ship_logs():
    content_type = request.content_type
    if content_type != 'application/json':
        return jsonify({'error': 'Unsupported Media Type'}), 415

    data = request.get_json(silent=True)
    if not data or 'payload' not in data or 'signature' not in data:
        return jsonify({'error': 'Missing payload or signature'}), 400

    payload_bytes = data['payload'].encode('utf-8')
    signature = data['signature']

    if not _verify_signature(payload_bytes, signature):
        return jsonify({'error': 'Invalid signature'}), 401

    iv = data.get('iv')
    encrypted_content = data.get('encrypted_content')

    if not iv or not encrypted_content:
        return jsonify({'error': 'Missing encryption parameters'}), 400

    decoded_content = bytes.fromhex(encrypted_content)
    decoded_iv = bytes.fromhex(iv)

    plaintext = _decrypt_data(decoded_content, decoded_iv)
    if plaintext is None:
        return jsonify({'error': 'Decryption failed'}), 400

    try:
        log_entry = json.loads(plaintext.decode('utf-8'))
    except (json.JSONDecodeError, UnicodeDecodeError):
        return jsonify({'error': 'Invalid log format'}), 400

    logging.info("Received log: %s", log_entry)
    return jsonify({'status': 'accepted'}), 202
