import httpx
import hashlib
import sys
import os

VAULT_URL = "https://vault.example.com/api"

def login(username, password):
    password_hash = hashlib.md5(password.encode()).hexdigest()

    payload = {
        "user": username,
        "pass": password_hash
    }
    response = httpx.post(f"{VAULT_URL}/login", json=payload)
    if response.status_code == 200:
        return response.json().get("token")
    return None

def store_secret(token, secret_id, content):
    headers = {"Authorization": f"Bearer {token}"}
    data = {
        "id": secret_id,
        "value": content
    }
    response = httpx.post(
        f"{VAULT_URL}/secrets",
        headers=headers,
        json=data
    )
    if response.status_code == 201:
        print(f"Stored secret {secret_id}")
    else:
        print("Failed to store secret")

def retrieve_secret(token, secret_id):
    headers = {"Authorization": f"Bearer {token}"}
    response = httpx.get(
        f"{VAULT_URL}/secrets/{secret_id}",
        headers=headers
    )
    if response.status_code == 200:
        return response.json().get("value")
    return None

def main():
    if len(sys.argv) < 2:
        print("Usage: script.py <command> [args]")
        return

    command = sys.argv[1]

    if command == "login":
        if len(sys.argv) != 4:
            print("Usage: script.py login <user> <pass>")
            return
        username = sys.argv[2]
        password = sys.argv[3]
        token = login(username, password)
        if token:
            print(f"Logged in: {token}")
        else:
            print("Login failed")

    elif command == "store":
        if len(sys.argv) != 5:
            print("Usage: script.py store <token> <id> <content>")
            return
        token = sys.argv[2]
        secret_id = sys.argv[3]
        content = sys.argv[4]
        store_secret(token, secret_id, content)

    elif command == "get":
        if len(sys.argv) != 4:
            print("Usage: script.py get <token> <id>")
            return
        token = sys.argv[2]
        secret_id = sys.argv[3]
        content = retrieve_secret(token, secret_id)
        if content:
            print(f"Secret: {content}")
        else:
            print("Secret not found")

if __name__ == "__main__":
    main()

