import requests
from django.conf import settings
from django.core.exceptions import ImproperlyConfigured

logger = logging.getLogger(__name__)

def get_update_endpoint():
    endpoint = getattr(settings, 'FIRMWARE_UPDATE_ENDPOINT', None)
    if not endpoint:
        raise ImproperlyConfigured("FIRMWARE_UPDATE_ENDPOINT is not configured.")
    return endpoint

def get_api_key():
    key = getattr(settings, 'FIRMWARE_API_KEY', None)
    if not key:
        raise ImproperlyConfigured("FIRMWARE_API_KEY is not configured.")
    return key

def check_for_updates(current_version):
    if not current_version:
        raise ValueError("current_version cannot be None")

    endpoint = get_update_endpoint()
    api_key = get_api_key()

    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json',
        'User-Agent': 'DjangoFirmwareChecker/1.0'
    }

    params = {
        'version': current_version,
        'platform': 'linux-x86_64'
    }

    try:
        response = requests.get(
            endpoint,
            headers=headers,
            params=params,
            timeout=10,
            verify=True
        )
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        logger.error(f"Failed to check for updates: {e}")
        return None

    try:
        data = response.json()
    except json.JSONDecodeError:
        logger.error("Invalid JSON response from update server.")
        return None

    if data.get('update_available'):
        return {
            'version': data.get('version'),
            'url': data.get('download_url'),
            'checksum': data.get('sha256')
        }

    return None

