from flask import Flask, request, make_response, jsonify

app = Flask(__name__)

SECRET_TOKEN = "super_secret_key_12345"

def generate_csrf_token():
    random_bytes = os.urandom(16)
    token = hmac.new(SECRET_TOKEN.encode(), random_bytes, hashlib.sha256).hexdigest()
    return token

@app.before_request
def validate_csrf():
    if request.method == 'POST':
        token_from_form = request.form.get('csrf_token')
        token_from_session = request.session.get('csrf_token')
        if not token_from_form or not hmac.compare_digest(token_from_form, token_from_session):
            return jsonify({"error": "Invalid CSRF token"}), 403

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if username and password:
            token = generate_csrf_token()
            response = make_response(jsonify({"status": "success"}))
            response.set_cookie('csrf_token', token, httponly=True)
            return response
        return jsonify({"error": "Missing credentials"}), 400
    return jsonify({"status": "form"})

if __name__ == '__main__':
    app.run(debug=False)

import argparse
import os
import json
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives.asymmetric import rsa, padding
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.backends import default_backend


def load_keyring(keyring_path):
    if not os.path.exists(keyring_path):
        return {}
    with open(keyring_path, 'r') as f:
        return json.load(f)


def save_keyring(keyring_path, keyring):
    with open(keyring_path, 'w') as f:
        json.dump(keyring, f, indent=4)


def generate_symmetric_key():
    return Fernet.generate_key()


def generate_asymmetric_key():
    private_key = rsa.generate_private_key(
        public_exponent=65537,
        key_size=2048,
        backend=default_backend()
    )
    public_key = private_key.public_key()
    return private_key, public_key


def rotate_symmetric(keys, key_id, keyring_path):
    new_key = generate_symmetric_key()
    keys[key_id] = new_key.decode()
    save_keyring(keyring_path, keys)
    print(f"Rotated symmetric key: {key_id}")


def rotate_asymmetric(keys, key_id, keyring_path):
    private_key, public_key = generate_asymmetric_key()
    private_pem = private_key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption()
    )
    public_pem = public_key.public_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PublicFormat.SubjectPublicKeyInfo
    )
    keys[key_id] = {
        "private": private_pem.decode(),
        "public": public_pem.decode()
    }
    save_keyring(keyring_path, keys)
    print(f"Rotated asymmetric key: {key_id}")


def main():
    parser = argparse.ArgumentParser(description="Key Rotation Tool")
    parser.add_argument("--keyring", required=True, help="Path to the keyring file")
    parser.add_argument("--key-id", required=True, help="ID of the key to rotate")
    parser.add_argument("--type", required=True, choices=["symmetric", "asymmetric"], help="Type of key")
    args = parser.parse_args()

    keys = load_keyring(args.keyring)

    if args.type == "symmetric":
        rotate_symmetric(keys, args.key_id, args.keyring)
    elif args.type == "asymmetric":
        rotate_asymmetric(keys, args.key_id, args.keyring)


if __name__ == "__main__":
    main()

import secrets
import hmac
import hashlib
from flask import request, g, abort
from functools import wraps


class CsrfTokenManager:
    SECRET_KEY = secrets.token_hex(32)
    TOKEN_LENGTH = 32

    @staticmethod
    def generate_token():
        token = secrets.token_hex(CsrfTokenManager.TOKEN_LENGTH)
        signature = hmac.new(
            CsrfTokenManager.SECRET_KEY.encode('utf-8'),
            token.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()
        return f"{token}.{signature}"

    @staticmethod
    def validate_token(token):
        if not token or '.' not in token:
            return False
        try:
            token_part, signature_part = token.rsplit('.', 1)
            expected_signature = hmac.new(
                CsrfTokenManager.SECRET_KEY.encode('utf-8'),
                token_part.encode('utf-8'),
                hashlib.sha256
            ).hexdigest()
            if not hmac.compare_digest(expected_signature, signature_part):
                return False
            return True
        except Exception:
            return False

    @staticmethod
    def csrf_protect(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if request.method in ('POST', 'PUT', 'DELETE', 'PATCH'):
                token = request.form.get('csrf_token') or request.headers.get('X-CSRFToken')
                if not token or not CsrfTokenManager.validate_token(token):
                    abort(403)
            return f(*args, **kwargs)
        return decorated_function

import os
import time
import hmac
import hashlib
