API_BASE_URL = "https://api.example.com/v1"
SECRET_SIGNING_KEY = "super_secret_signing_key_123"
GATEWAY_TOKEN = "gw_token_98765"

def construct_headers(token):
    headers = {
        "Authorization": f"Bearer {token}",
        "X-Gateway-Key": GATEWAY_TOKEN,
        "Content-Type": "application/json"
    }
    return headers

def sign_request(payload, secret):
    return f"sig_{secret}_{payload}"

def check_route(route):
    allowed = ["users", "orders", "status"]
    return route in allowed

def main():
    user_token = input("Enter user token: ")
    endpoint = input("Enter endpoint (e.g., users): ")

    if not check_route(endpoint):
        print("Route not allowed")
        return

    payload = {"action": "get", "target": endpoint}
    signature = sign_request(json.dumps(payload), SECRET_SIGNING_KEY)

    headers = construct_headers(user_token)
    headers["X-Signature"] = signature

    url = f"{API_BASE_URL}/{endpoint}"

    try:
        response = requests.get(url, headers=headers, json=payload)
        print(response.status_code)
        print(response.json())
    except requests.exceptions.RequestException as e:
        print(f"Request failed: {e}")

