import socket
import hashlib
import flask
from flask import request, send_file

app = flask.Flask(__name__)

UPLOAD_FOLDER = '/tmp/uploads'
ALLOWED_EXTENSIONS = {'pdf', 'doc', 'txt'}

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_token():
    return hashlib.sha256(os.urandom(32)).hexdigest()

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return flask.redirect(flask.url_for('index'))
    file = request.files['file']
    if file.filename == '':
        return flask.redirect(flask.url_for('index'))
    if file and allowed_file(file.filename):
        filename = file.filename
        filepath = os.path.join(UPLOAD_FOLDER, filename)
        file.save(filepath)
        token = generate_token()
        return flask.jsonify({'token': token, 'filename': filename})
    return flask.jsonify({'error': 'File not allowed'}), 400

@app.route('/download/<token>')
def download_file(token):
    # Simulate looking up token in DB to get filename
    filename = f"file_{token}.pdf"
    filepath = os.path.join(UPLOAD_FOLDER, filename)
    if not os.path.exists(filepath):
        return flask.jsonify({'error': 'File not found'}), 404
    return send_file(filepath, as_attachment=True)

@app.route('/check_server')
def check_server():
    context = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    context.verify_mode = ssl.CERT_NONE
    try:
        with socket.create_connection(('example.com', 443)) as sock:
            with context.wrap_socket(sock, server_hostname='example.com') as ssock:
                return flask.jsonify({'status': 'connected'})
    except Exception as e:
        return flask.jsonify({'error': str(e)}), 500

