import os
import hmac
import hashlib
import secrets
from django.utils.deprecation import MiddlewareMixin

def get_signing_key():
    key = os.environ.get('DJANGO_SESSION_SIGNING_KEY')
    if not key:
        raise ValueError("DJANGO_SESSION_SIGNING_KEY environment variable is not set")
    return key

def create_session_token(token_data, signing_key):
    message = token_data.encode('utf-8')
    signature = hmac.new(signing_key.encode('utf-8'), message, hashlib.sha256).hexdigest()
    return f"{message.decode('utf-8')}:{signature}"

def verify_session_token(token_string, signing_key):
    if ':' not in token_string:
        return None
    message_part, signature_part = token_string.rsplit(':', 1)
    expected_signature = hmac.new(signing_key.encode('utf-8'), message_part.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected_signature, signature_part):
        return None
    return message_part

class SecureSessionMiddleware(MiddlewareMixin):
    def process_request(self, request):
        signing_key = get_signing_key()
        session_token = request.COOKIES.get('session_token')
        if session_token:
            request.session_data = verify_session_token(session_token, signing_key)
        else:
            request.session_data = None

    def process_response(self, request, response):
        if hasattr(request, 'session_data') and request.session_data:
            signing_key = get_signing_key()
            token = create_session_token(request.session_data, signing_key)
            response.set_cookie(
                'session_token',
                token,
                httponly=True,
                secure=True,
                samesite='Lax',
                max_age=3600
            )
        return response

