class EmailVerificationService:
    def __init__(self, secret_key: bytes):
        if not isinstance(secret_key, bytes) or len(secret_key) != 32:
            raise ValueError("Secret key must be 32 bytes.")
        self._secret_key = secret_key

    def generate_token(self, email: str) -> str:
        nonce = secrets.token_bytes(16)
        message = f"{email}:{nonce.hex()}".encode('utf-8')
        mac = hmac.new(self._secret_key, message, hashlib.sha256).digest()
        token_data = nonce + mac
        return token_data.hex()

    def verify_token(self, token: str, email: str) -> bool:
        try:
            token_bytes = bytes.fromhex(token)
            if len(token_bytes) != 48:
                return False
            nonce = token_bytes[:16]
            stored_mac = token_bytes[16:]
            message = f"{email}:{nonce.hex()}".encode('utf-8')
            expected_mac = hmac.new(self._secret_key, message, hashlib.sha256).digest()
            return hmac.compare_digest(stored_mac, expected_mac)
        except Exception:
            return False

