from typing import Optional, Dict


http = urllib3.PoolManager()


def generate_token() -> str:
    return secrets.token_urlsafe(32)


def upload_file(file_path: str, upload_url: str, token: str) -> Dict:
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    with open(file_path, 'rb') as f:
        file_data = f.read()

    file_hash = hashlib.sha256(file_data).hexdigest()

    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/octet-stream',
        'X-File-Hash': file_hash
    }

    response = http.request(
        'POST',
        upload_url,
        body=file_data,
        headers=headers
    )

    if response.status != 200:
        raise Exception(f"Upload failed with status {response.status}")

    return response.json()


def download_file(file_id: str, download_url: str, token: str, expected_hash: str) -> bytes:
    headers = {
        'Authorization': f'Bearer {token}'
    }

    response = http.request(
        'GET',
        f"{download_url}/{file_id}",
        headers=headers
    )

    if response.status != 200:
        raise Exception(f"Download failed with status {response.status}")

    file_data = response.data

    actual_hash = hashlib.sha256(file_data).hexdigest()

    if not hmac.compare_digest(actual_hash, expected_hash):
        raise ValueError("File integrity check failed")

    return file_data


def validate_token(token: str, secret_key: str) -> bool:
    if not token or not secret_key:
        return False

    parts = token.split('.')
    if len(parts) != 2:
        return False

    signature, payload = parts

    expected_signature = hmac.new(
        secret_key.encode('utf-8'),
        payload.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()

    return hmac.compare_digest(signature, expected_signature)

