def generate_state_token() -> str:
    return secrets.token_urlsafe(32)

def create_state_payload(state: str, user_id: str) -> str:
    payload = f"{user_id}:{state}"
    return base64.urlsafe_b64encode(payload.encode()).decode()

def verify_state_signature(state_payload: str, user_id: str, secret: str) -> bool:
    try:
        decoded = base64.urlsafe_b64decode(state_payload)
        payload_user_id, original_state = decoded.decode().split(":", 1)
    except Exception:
        return False

    if payload_user_id != user_id:
        return False

    expected_signature = create_signature(original_state, secret)
    actual_signature = state_payload.split(":")[-1] if ":" in state_payload else ""

    if len(actual_signature) != len(expected_signature):
        return False

    return hmac.compare_digest(expected_signature, actual_signature)

def create_signature(data: str, secret: str) -> str:
    return hmac.new(secret.encode(), data.encode(), hashlib.sha256).hexdigest()

def handle_callback(state: str, code: str, client_id: str, client_secret: str, redirect_uri: str, token_endpoint: str, state_secret: str) -> dict:
    if not state or not code:
        raise ValueError("State and code are required")

    expected_state = state
    if not verify_state_signature(state, "current_user", state_secret):
        raise ValueError("Invalid state signature")

    async def fetch_token():
        async with httpx.AsyncClient(verify=True) as client:
            response = await client.post(
                token_endpoint,
                data={
                    "grant_type": "authorization_code",
                    "code": code,
                    "client_id": client_id,
                    "client_secret": client_secret,
                    "redirect_uri": redirect_uri
                },
                timeout=10.0
            )
            response.raise_for_status()
            return response.json()

    return fetch_token()

