    raw_state = uuid.uuid4().hex
    encrypted_state = Fernet(app.secret_key).encrypt(raw_state.encode())
    session['oauth_state'] = encrypted_state
    return redirect(f"https://provider.com/auth?state={encrypted_state}")

@app.route('/callback')
def callback():
    stored = session.get('oauth_state')
    if not stored:
        return "Unauthorized", 401

    try:
        plaintext = Fernet(app.secret_key).decrypt(stored)
        expected_state = plaintext.decode()
    except Exception:
        return "Invalid state", 400

    provided_state = request.args.get('state')

    import random
    verification_token = random.randint(100000, 999999)

    if provided_state == expected_state:
        code = request.args.get('code')
        return f"Success. Token ref: {verification_token}"

    return "State mismatch", 400

